rep("\n.mur .ed-part{", r"""
/* (p1) l'atelier */
.vue-atelier #chr,.vue-atelier #heure,.vue-atelier #bfin,.vue-atelier #btableau,.vue-atelier #bvideoproj,.vue-atelier #bqui,.vue-atelier .outils,.vue-atelier #compte,.vue-atelier #al-boite,.vue-atelier #al-ligne{display:none !important}.vue-atelier #outils-atelier{display:flex !important}.vue-atelier #droite-fin,.vue-atelier .suivante,.vue-atelier #suivi,.vue-atelier .suivi,.vue-atelier #droite > :not(#droite-atelier){display:none !important}.vue-atelier #droite-atelier{display:block !important}#droite-atelier{display:none}.vue-atelier #numero + *{display:none !important}
.outils-atelier{display:flex;gap:8px;align-items:center;padding:6px 0;font-size:.9rem;color:var(--texte2)}.outils-atelier .btn{padding:5px 10px}.outils-atelier .at-taille{margin-left:8px}.outils-atelier .at-save{margin-left:auto;color:var(--joue);font-size:.85rem}
.at-chap{font-size:.86rem}.at-chap .sea{margin:6px 0 4px;color:var(--or);font-weight:700;font-size:.8rem;letter-spacing:.04em}.at-chap .sea2{margin:8px 0 4px;color:var(--texte2);font-weight:700;font-size:.8rem}.at-chap .fr{margin:8px 0 4px;padding:3px 6px;border-top:1px dashed var(--bord2);color:var(--texte2);font-size:.75rem;display:flex;justify-content:space-between;gap:6px}.at-chap .fr .plus{color:#ff8a8e;font-weight:700}.at-chap .d{display:flex;gap:6px;align-items:center;padding:3px 6px;border-radius:6px;color:var(--texte2);cursor:pointer}.at-chap .d:hover{background:var(--carte)}.at-chap .d.on{background:var(--carte);color:var(--texte);border:1px solid var(--or)}.at-chap .d .n{width:18px;color:var(--sourd);text-align:right;flex:none}.at-chap .d .t{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.at-chap .d .a{font-size:.7rem;color:var(--or);flex:none}.at-chap .d .h{font-size:.72rem;color:var(--sourd);flex:none}.at-chap .aide{color:var(--sourd);font-size:.75rem;margin-top:10px}
.at-d{background:var(--carte);border:1px solid var(--bord);border-radius:8px;padding:8px 12px;margin-bottom:8px;font-size:.88rem}.at-d h5{margin:0 0 4px;font-size:.72rem;letter-spacing:.06em;color:var(--or)}.at-d .l{padding:2px 0;color:var(--texte2)}.at-d .l b{color:var(--texte)}.at-d .ok{color:var(--joue)}.at-d .al{color:#ff8a8e}.at-d .al i{display:block;color:var(--texte2);font-size:.8rem}.at-note{color:var(--sourd);font-size:.75rem}
.mur .ed-part{""")
