rep("function rendre(mur, et){ if (et && et.oral && !et.pilote) {","function rendre(mur, et){ if (et && et.atelier && et.pilote) { et = Object.assign({}, et, { nDev: elements(DATA.seances[et.si].ecrans[et.di]).length }); } if (et && et.oral && !et.pilote) {")
# le volet et la colonne de droite de l'atelier ; le numéro ; « Jouer en avance »
rep("function tout(){", r"""function creneauDe(di){ /* l'heure prévue d'une diapo : la base de son heure + le cumul des durées avant elle */ const E = seance().ecrans; const h = E[di].heure; const o = ordreHeure(h); let t = HEURES_SIM[h] ? HEURES_SIM[h].base : 0; for (const i of o) { if (i === di) break; t += (E[i].dur || 0) * 60000; } return { debut: t, fin: t + (E[di].dur || 0) * 60000 }; }
function voletAtelier(){ const E = seance().ecrans; const heures = [...new Set(E.map(e => e.heure))].sort(); const acts = DATA.activites[String(S.si)] || []; const numA = i => { const a = actDe(E[i]); return a ? 'A' + a.num : ''; }; let h = `<div class="at-chap"><div class="sea">Chapitre · ${esc(seance().titre)}</div><div class="sea2">Séance 1 — ${esc(seance().titre.split(':')[0].trim())} (${heures.length} h)</div>`; heures.forEach(hh => { const o = ordreHeure(hh); const prevu = o.filter(i => E[i].role !== 'fin').reduce((t, i) => t + (E[i].dur || 0), 0); const sim = HEURES_SIM[hh]; const dep = prevu + 5 - 50; h += `<div class="fr"><span>H${hh} · ${sim ? esc(sim.jour.replace(/ 2026$/, '')) : ''} · 55 min</span><span>${prevu} + 5 = ${prevu + 5} min ${dep > 0 ? '<span class="plus" title="Ce que l\'heure dépasse : réduis une durée ou déplace une diapo">+' + dep + '</span>' : '<span style="color:var(--joue)">✔</span>'}</span></div>`; o.forEach(i => { const e = E[i]; h += `<div class="d${i === S.di ? ' on' : ''}" data-at-di="${i}" title="Ouvre cette diapo dans l'atelier"><span class="n">${rangDe(i, hh)}</span><span class="t">${e.role === 'fin' ? 'Cahier de textes' : esc(e.act)}</span>${e.role === 'fin' ? '' : '<span class="a">' + numA(i) + '</span>'}<span class="h">${e.role === 'fin' ? 5 : (e.dur || 0)} min</span></div>`; }); }); h += `<div class="sea2" style="color:var(--sourd)">Séance 2 — (à venir dans la maquette) · H3</div><div class="aide">Ctrl + molette : zoom · clic droit : dupliquer, insérer, envoyer… (à venir : p3)</div></div>`; return h; }
function droiteAtelier(){ const E = seance().ecrans; const e = ecran(); const a = actDe(e); const dA = a ? diaposAct(a) : [e]; const rang = a ? dA.indexOf(S.di) + 1 : 1; const cr = creneauDe(S.di); const sim = HEURES_SIM[e.heure]; const comp = (e.comp || []).map(libNotion); const remob = (e.remob || []).map(libNotion); const nEl = elements(e).length;
  let x = `<div class="at-d"><h5>CE QUE LA DIAPO DÉCLARE</h5><div class="l">${a ? '<b>Activité ' + a.num + '</b> — ' + esc(a.titre) + ' · diapo ' + rang + ' sur ' + dA.length + ' de l\'activité' : (e.role === 'fin' ? '<b>Cahier de textes</b> — les cinq minutes réservées' : '<i>hors activité</i>')}</div><div class="l">Heure prévue : <b>H${e.heure}</b>${sim ? ' (' + esc(sim.jour.replace(/ 2026$/, '')) + ')' : ''} · <b>${e.role === 'fin' ? 5 : (e.dur || 0)} min</b> · ${hhmm(cr.debut)} → ${hhmm(cr.fin)} — <span class="at-note">proposée d'après les durées ; déplaçable</span></div><div class="l">Notions travaillées : ${comp.length ? comp.map(n => '<b>' + esc(n) + '</b>').join(', ') : '<i>aucune</i>'}</div><div class="l">Remobilise : ${remob.length ? remob.map(n => '<b>' + esc(n) + '</b>').join(', ') : '<i>rien</i>'}</div><div class="l">Éléments : ${nEl}${nEl > 1 ? ' · dévoilés un par un' : ''}</div></div>`;
  /* pour la classe : le temps et les notions */ const alertes = []; const h = e.heure; const o = ordreHeure(h); const prevu = o.filter(i => E[i].role !== 'fin').reduce((t, i) => t + (E[i].dur || 0), 0); const dep = prevu + 5 - 50; if (dep > 0) alertes.push(`⚠ L'heure ${h} dépasse de ${dep} min<i>${prevu} min d'activités + 5 min de cahier pour 50 utiles — le T-5 le redira ; réduis une durée ou déplace une diapo</i>`); const compTous = new Set(E.flatMap(z => z.comp || [])); E.forEach((z, i) => (z.remob || []).forEach(id => { const avant = E.some((y, j) => j < i && (y.comp || []).includes(id)); if (!avant) alertes.push(`⚠ « ${esc(z.act)} » (H${z.heure}) remobilise une notion que rien ne travaille avant<i>« ${esc(libNotion(id))} »${compTous.has(id) ? ' est travaillée plus tard — remonte l\'activité qui la travaille, ou change l\'ordre' : ' n\'est travaillée nulle part dans le chapitre'}</i>`); })); const jamais = [...new Set(E.flatMap(z => z.remob || []))].filter(id => !compTous.has(id)); if (jamais.length) alertes.push(`⚠ ${jamais.length} notion${jamais.length > 1 ? 's' : ''} remobilisée${jamais.length > 1 ? 's' : ''} ${jamais.length > 1 ? 'ne sont travaillées' : 'n\'est travaillée'} par aucune activité<i>${jamais.map(id => '« ' + esc(libNotion(id)) + ' »').join(', ')} — prévue${jamais.length > 1 ? 's' : ''} nulle part</i>`); x += `<div class="at-d"><h5>POUR LA CLASSE — le temps et les notions</h5>${alertes.length ? alertes.map(t => '<div class="l al">' + t + '</div>').join('') : '<div class="l ok">✔ Rien à signaler : l\'heure tient, les notions remobilisées sont travaillées avant</div>'}</div>`;
  /* sur la forme : seulement s'il y a quelque chose à dire */ const forme = []; (e.blocs || []).forEach((b, bi) => { if (b.t === 'fiche' && !b.feuille) forme.push(`⚠ La fiche « ${esc(b.txt || '')} » (bloc ${bi + 1}) n'est liée à aucune feuille du chapitre<i>lie-la à une feuille, ou le bloc ne s'affichera pas (cadrage 4, 1.7)</i>`); if ((b.t === 'html' || b.t === 'page') && !b.contrat) forme.push(`⚠ « ${esc(b.txt || 'page')} » est une page HTML sans contrat de pilotage<i>l'objet manque à l'éditeur : le texte prêt à copier pour l'instance est dans « À régler » (4.3)</i>`); if (b.t === 'video' && b.src && !/^(https?:|\/|\.)/.test(b.src)) forme.push(`⚠ La vidéo « ${esc(b.txt || '')} » pointe vers un fichier non atteignable<i>vérifie le chemin ou la clé USB (4 bis)</i>`); }); if (forme.length) x += `<div class="at-d"><h5>SUR LA FORME — ce qui peut casser en classe</h5>${forme.map(t => '<div class="l al">' + t + '</div>').join('')}<div class="at-note">Ces alertes ne s'affichent jamais pendant une heure réelle : elles se règlent ici, ou dans « À régler » du chapitre.</div></div>`;
  /* le chapitre */ const acts = DATA.activites[String(S.si)] || []; const nH = [...new Set(E.map(z => z.heure))].length; const notions = [...new Set(E.flatMap(z => (z.comp || []).concat(z.remob || [])))]; const trav = notions.filter(id => compTous.has(id)); x += `<div class="at-d"><h5>LE CHAPITRE</h5><div class="l">1 séance dans la maquette · ${nH} h · ${E.length} diapos · ${acts.length} activités · notions : ${notions.length}, <span class="ok">travaillées : ${trav.length}</span>${notions.length - trav.length ? ', <span class="al">jamais travaillées : ' + (notions.length - trav.length) + '</span>' : ''}</div><div class="l">Pages HTML : <b>${E.reduce((t, z) => t + (z.blocs || []).filter(b => b.t === 'html' || b.t === 'page').length, 0)}</b> · objets manquants à l'éditeur : <b>0</b> <span class="at-note">(à faire tendre vers zéro, 4.4)</span></div></div>`; return x; }
function tout(){ if (S.atelier) { const v = $('volet'); if (v) { const hv = voletAtelier(); if (v.dataset.atelier !== hv) { v.innerHTML = hv; v.dataset.atelier = hv; v.querySelectorAll('[data-at-di]').forEach(d => d.onclick = () => { S.di = +d.dataset.atDi; S.page = null; journal('atelier-diapo', { di: S.di }); tout(); }); } } const da = $('droite-atelier'); if (da) { const hd = droiteAtelier(); if (da.innerHTML !== hd) da.innerHTML = hd; } const aj = $('at-jouer'); if (aj && !aj._ok) { aj._ok = true; aj.onclick = () => { journal('atelier-jouer-en-avance', { di: S.di }); voir('pilotage'); }; } }""")
