rep("$('numero').textContent = `${rangDe(S.di) ? 'Diapo ' + rangDe(S.di) + ' sur ' + ordreHeure(S.heure).length","$('numero').innerHTML = S.atelier ? (function(){ const e = ecran(); const a = actDe(e); const cr = creneauDe(S.di); return `<b>Atelier · Diapo ${rangDe(S.di, e.heure)} sur ${ordreHeure(e.heure).length} · heure ${e.heure}${a ? ' · activité ' + a.num : ''} · ${esc(e.role === 'fin' ? 'Cahier de textes' : e.act)}</b> <span style=\"color:var(--texte2)\">· prévue ${e.role === 'fin' ? 5 : (e.dur || 0)} min · H${e.heure} ${hhmm(cr.debut).replace(':', ' h ')} → ${hhmm(cr.fin).replace(':', ' h ')}</span>`; })() : `${rangDe(S.di) ? 'Diapo ' + rangDe(S.di) + ' sur ' + ordreHeure(S.heure).length")
